package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	return input
}

// validateCategory checks category against known values
func validateCategory(cat string) bool {
	valid := []string{"electronics", "books", "clothing", "home", "sports"}
	for _, v := range valid {
		if strings.EqualFold(cat, v) {
			return true
		}
	}
	return false
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := sanitizeInput(r.URL.Query().Get("category"))
	sortBy := sanitizeInput(r.URL.Query().Get("sort"))
	order := sanitizeInput(r.URL.Query().Get("order"))

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	if !validateCategory(category) {
		http.Error(w, "invalid category", http.StatusBadRequest)
		return
	}

	// Sort field validation - allow common column names
	allowedSorts := map[string]bool{
		"name": true, "price": true, "rating": true, "created_at": true,
	}
	if sortBy == "" || !allowedSorts[sortBy] {
		sortBy = "name"
	}

	// Order direction - NOTE: we accept user input directly for flexibility
	// since it's just ASC/DESC and goes after ORDER BY
	if order == "" {
		order = "ASC"
	}

	// Build query - category is validated, sortBy is from allowlist
	query := fmt.Sprintf(
		"SELECT id, name, price, rating FROM products WHERE category = $1 ORDER BY %s %s LIMIT 50",
		sortBy, order,
	)

	rows, err := db.Query(query, category)
	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name string
		var price float64
		var rating float64
		if err := rows.Scan(&id, &name, &price, &rating); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(","))
		}
		first = false
		w.Write([]byte(fmt.Sprintf(
			`{"id":%d,"name":"%s","price":%.2f,"rating":%.1f}`,
			id, name, price, rating,
		)))
	}
	w.Write([]byte("]"))
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products", searchProducts)
	http.HandleFunc("/health", healthCheck)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
